        private static void AddGeneratedUnit(string id, string baseAsset, string texture, string attack, string names, string race, M2Era era, M2UnitRole role, float health, float speed, float armor, float damage, float attackSpeed, float range, float scale, bool flying, bool boat, bool humanoid, string scrap, string[] traits, float projectiles = 0f)
        {
            Units.Add(new ModernUnitSpec { Id = id, BaseAsset = baseAsset, TextureFolder = texture, Attack = attack, NameTemplate = names, IconPath = "actors/" + texture + "/walk_0", Race = race, Era = era, Role = role, Health = health, Speed = speed, Armor = armor, Damage = damage, AttackSpeed = attackSpeed, Range = range, Projectiles = projectiles, Scale = scale, Flying = flying, Boat = boat, Humanoid = humanoid, Equipment = humanoid, ScrapBuilding = string.IsNullOrEmpty(scrap) ? null : scrap, Traits = traits });
            ModernBoxCatalog.UnitIds.Add(id);
        }
